\end{remark}

\bpnode{rem:pet-ch4-ex-8}
\begin{remark}[horizontal and mixed curvature formulas]
  \label{rem:pet-ch4-ex-8}

  \source{petersen:page-0172}
  \uses{rem:pet-ch4-ex-7, thm:pet-ch4-oneill-formula}
